mapper.select:
select context_id, expert_user_id, external_task_id, task_type,
       service_start, service_end, service_mode, service_region, industry,
       occupancy_status, conflict_status, source_system, source_kind,
       source_version, verified_at, create_by, create_time, update_by, update_time
from expert_business_context_snapshot
where expert_user_id = #{userId}
  and service_start < #{serviceEnd}
  and service_end > #{serviceStart}
  and occupancy_status in ('FREE', 'OCCUPIED', 'BLOCKED')
order by verified_at desc, context_id desc

mapper.update:
update expert_service_evidence
set processing_status = #{processingStatus}, update_time = sysdate()
where evidence_id = #{evidenceId}
